"""Prototype the Wikisource bot using local file I/O instead of live server I/O.

Exercises the same edit logic as main_ws_bot.py real but reads and writes local
files rather than making live Wikisource API calls.

Usage (run from repo root):
    .venv/Scripts/python.exe py/main_ws_bot.py proto --edits path.json
"""

import argparse

from mb_cmn import bib_locales as tbn
from mb_cmn import file_io
from mb_cmn import mam_bknas_and_std_bknas as mbkn_a_sbkn
from mb_cmn.my_utils import dkv_map
from mb_cmn.my_utils import dv_map
from mb_misc.my_utils_for_mainish import show_progress_g
from ws import ws_bot_edit as wbe
from ws import ws_download_selector as wsds
from ws import ws_fmt_2_back_to_wikitext as btw
from ws import ws_get_bk_in_both_fmts as wsin


def almost_main(edits_json_path=None, book_plans=None):
    """
    Prototypes the bot by using local file I/O rather than server I/O.
    """
    if edits_json_path is not None:
        edits_ctx = wbe.load_edits(edits_json_path)
    else:
        edits_ctx = wbe.no_edits()
    if book_plans is None:
        book_plans = list(wsds.selected_book_plans(_default_selector_args()))
    for book_plan in book_plans:
        he_bn_sbn, requested_he_chnus = book_plan
        bk39id = mbkn_a_sbkn.MAM_HBNP_TO_BK39ID[he_bn_sbn]
        show_progress_g(__file__, "book", bk39id)
        wsf2_book = wsin.get_bk_in_fmt_2(_IN_PATH, bk39id)
        out_book = dkv_map(
            (_edit_if_requested, edits_ctx, bk39id, set(requested_he_chnus)),
            wsf2_book,
        )
        osdf = tbn.ordered_short_dash_full_39(bk39id)
        _write_book_lines(osdf, out_book)
        _write_book_fmt_2(osdf, out_book)
    wbe.write_warnings(edits_ctx, _OUT_PATH_WARNINGS)
    wbe.write_modified_chapters(edits_ctx, _OUT_PATH_MODIFIED_CHAPTERS)


def _edit_if_requested(edits_ctx, bkid, requested_he_chnus, he_chnu, cif2):
    if he_chnu not in requested_he_chnus:
        return cif2, btw.big_str(he_chnu, cif2)
    return wbe.edit_cif2(edits_ctx, bkid, he_chnu, cif2)


def _default_selector_args():
    parser = argparse.ArgumentParser(add_help=False)
    wsds.add_selector_opts(parser)
    args = parser.parse_args([])
    wsds.validate_selector_args(args, parser)
    return args


_IN_PATH = "in/mam-ws"
_OUT_PATH_LINES = "out/mam-ws-bot/proto"
_OUT_PATH_FMT_2 = "out/mam-ws-bot/proto-fmt-2"
_OUT_PATH_MISC = "out/mam-ws-bot/proto-misc"
_OUT_PATH_WARNINGS = f"{_OUT_PATH_MISC}/warnings.json"
_OUT_PATH_MODIFIED_CHAPTERS = f"{_OUT_PATH_MISC}/modified-chapters.json"


def _write_book_lines(osdf, dic_from_hcn_to_book_pair):
    dic_from_hcn_to_lines = dv_map(_splitlines, dic_from_hcn_to_book_pair)
    out_path = f"{_OUT_PATH_LINES}/{osdf}.json"
    file_io.json_dump_to_file_path(dic_from_hcn_to_lines, out_path)


def _write_book_fmt_2(osdf, dic_from_hcn_to_book_pair):
    dic_from_hcn_to_fmt_2 = dv_map(_fmt_2, dic_from_hcn_to_book_pair)
    out_path_fmt_2 = f"{_OUT_PATH_FMT_2}/{osdf}.json"
    file_io.json_dump_to_file_path(dic_from_hcn_to_fmt_2, out_path_fmt_2)


def _splitlines(book_pair):
    _out_cif2, big_str = book_pair
    return big_str.splitlines()


def _fmt_2(book_pair):
    out_cif2, _big_str = book_pair
    return out_cif2
